39: export const ActivityHistoryList = ({
40:   targetId,
41:   entityType,
42: }: ActivityHistoryListProps): JSX.Element => {
43:   const { data, size, setSize, error } = useActivityHistory(targetId);
44: 
45:   const response = useMemo(() => {
46:     if (!data) return null;
47:     return data[size - 1];
48:   }, [data, size]);
49: 
50:   const { data: referenceData, error: errorReferenceData } = useReferenceData<
51:     | "answers"
52:     | "religion-belief"
53:     | "age-bracket"
54:     | "ethnic-group-a"
55:     | "gender"
56:     | "sexual-orientation"
57:   >({
58:     category: "equality-information",
59:   });
60: 
61:   if (errorReferenceData) {
62:     return (
63:       <ErrorSummary
64:         id="equality-information-error"
65:         title={locale.errors.unexpectedResponse}
66:         description={locale.errors.unexpectedResponseDescription}
67:       />
68:     );
69:   }
70: 
71:   if (error?.response?.status === 404) {
72:     return <NoActivityHistory />;
73:   }
74: 
75:   if (!response || !referenceData) {
76:     return (
77:       <Center>
78:         <Spinner />
79:       </Center>
80:     );
81:   }
82: 
83:   const {
84:     results: activityHistory,
85:     paginationDetails: { nextToken },
86:   } = response;
87: 
88:   return (
